function SceneManager.save()
    if currentScene and currentScene.save then currentScene.save() end
end

function PlayInput:axis(negativeButton, positiveButton)
    return (self:isDown(positiveButton) and 1 or 0) - (self:isDown(negativeButton) and 1 or 0)
end

function WalkingActions.new(controls)
    return setmetatable({ controls = controls, bButton = TapOrReel.new() }, WalkingActions)
end

function ExitDistance:proximity(x, y)
    if self.byBlock then
        local gridX, gridY = self.maze:blockAt(x, y)
        local distance = self.byBlock[(gridY - 1) * self.maze.gridWidth + gridX] or self.farthest + 1
        return 1 - math.min(1, distance / math.max(1, self.farthest))
    end
    local column, row = self.maze:nearestCell(x, y)
    return 1 - math.min(1, self:cells(column, row) / math.max(1, self.farthest))
end

function SideView.toScreen(worldX, worldY)
    local offsetX, offsetY = worldX - playerX, worldY - playerY
    return SideView.CENTER_X + (offsetX * cosine - offsetY * sine) * scale,
        SideView.CENTER_Y + (offsetX * sine + offsetY * cosine) * scale

function Raycaster.scan(maze, x, y, angle, screen, result)
    result = result or { runs = {}, depths = {} }
    result.runPool = result.runPool or {}

function Hum.levels(x, y, angle, items, levels)
    levels = levels or {}
    for index, item in ipairs(items) do
        local level = levels[index]
        if not level then
            level = {}
            levels[index] = level
        end
